import re

def parse(lines):
    hdr = re.compile(r'^(?P<type>[A-Za-z_$][\w.$]*) \{\s*$')
    kv = re.compile(r'^\s*(?P<key>[\w.$]+) = (?P<value>.*?)\s*$')
    thr = re.compile(r'^"(?P<name>.*)" \((?P<k>\w+) = (?P<v>[^)]*)\)$')
    frame = re.compile(r'^\s*(?P<method>\S.*?)\s+line: (?P<line>\d+)(?:\s+bci: (?P<bci>\d+))?\s*$')
    blocks = {}
    order = []
    frows = []
    flines = []
    skip = []
    n = len(lines)
    i = 0
    evno = 0
    while i < n:
        m = hdr.match(lines[i])
        if not m:
            i += 1
            continue
        typ = m.group('type')
        evno += 1
        rec = {'event': evno}
        used = [i]
        prefix = []
        i += 1
        while i < n:
            s = lines[i]
            t = s.strip()
            if t == '}':
                used.append(i)
                i += 1
                if prefix:
                    prefix.pop()
                    continue
                break
            if t == '':
                break
            mm = kv.match(s)
            if not mm:
                i += 1
                continue
            key = '.'.join(prefix + [mm.group('key')])
            val = mm.group('value')
            used.append(i)
            i += 1
            if val == '{':
                prefix.append(mm.group('key'))
                continue
            if val == '[':
                items = []
                while i < n and lines[i].strip() != ']':
                    it = lines[i].strip()
                    fm = frame.match(lines[i])
                    if fm:
                        frows.append({'event': evno, 'eventType': typ, 'field': key, 'method': fm.group('method'), 'line': fm.group('line'), 'bci': fm.group('bci') or ''})
                        flines.append(i)
                    elif it == '...' or it == '':
                        skip.append(i)
                    else:
                        items.append(it)
                        used.append(i)
                    i += 1
                if i < n:
                    used.append(i)
                    i += 1
                if items:
                    rec[key] = '; '.join(items)
                continue
            tm = thr.match(val)
            if tm:
                rec[key] = tm.group('name')
                rec[key + '.' + tm.group('k')] = tm.group('v')
            else:
                if len(val) >= 2 and val[0] == '"' and val[-1] == '"':
                    val = val[1:-1]
                rec[key] = val
        if typ not in blocks:
            blocks[typ] = {'lines': [], 'records': []}
            order.append(typ)
        blocks[typ]['lines'].extend(used)
        blocks[typ]['records'].append(rec)
    out = []
    for typ in order:
        b = blocks[typ]
        keys = []
        for r in b['records']:
            for k in r:
                if k not in keys:
                    keys.append(k)
        recs = [dict((k, r.get(k, '')) for k in keys) for r in b['records']]
        out.append({'name': typ, 'kind': 'table', 'lines': b['lines'], 'records': recs})
    if frows:
        out.append({'name': 'stackFrames', 'kind': 'table', 'lines': flines, 'records': frows})
    return {'blocks': out, 'skip': skip}

